    search_vector tsvector GENERATED ALWAYS AS (setweight(to_tsvector('english'::regconfig, public.search_text(VARIADIC ARRAY["firstName", "lastName", email, phone, address, "addressLine2", city, state, "postalCode", "customerStatus"])), 'A'::"char")) STORED,
    tenant_id uuid,
    ar_account_id uuid,
    ap_account_id uuid,
    currency text DEFAULT 'USD'::text NOT NULL,
    party_id uuid
);

